});
test('repeated maximum values', () => {
  expect(findMax([5, 5, 5])).toBe(5);
});
test('does not change the input', () => {
  const input = [3, 1, 2];
  findMax(input);
  expect(input).toEqual([3, 1, 2]);
});

solutions.code:
function findMax(numbers) {
  if (numbers.length === 0) return undefined;
  let max = numbers[0];
  for (const n of numbers) {
    if (n > max) max = n;
  }
  return max;
}
